export function resolveSeoForPath(pathname: string, lang: LangCode = 'en'): SeoMeta & { path: string } {
  const blogMatch = pathname.match(/^\/blog\/([^/]+)$/)
  if (blogMatch) {
    const slug = blogMatch[1]
    const post = BLOG_POSTS.find((p) => p.slug === slug)
    if (post) {
      return {
        path: pathname,
        title: post.title[lang] ?? post.title.en,
        description: post.excerpt[lang] ?? post.excerpt.en,
      }
    }
    return {
      path: pathname,
      title: 'Post Not Found',
      description: 'The requested MotoPass Insights article could not be found.',
    }
  }

  const meta = ROUTE_SEO[pathname]
  if (meta) {
    const localized = ROUTE_SEO_I18N[lang]?.[pathname]
    return { ...meta, ...localized, path: pathname }
  }

  return {
    path: pathname,
    title: 'Page Not Found',
    description: 'The page you requested does not exist on MotoPass.',
  }
}

export function absoluteUrl(path: string): string {
  if (path === '/') return `${SITE_URL}/`
  return `${SITE_URL}${path.startsWith('/') ? path : `/${path}`}`
}

/** Canonical URL with optional `?lang=` for non-English hreflang alternates. */
export function localizedUrl(path: string, lang: LangCode): string {
  const base = absoluteUrl(path)
  if (lang === 'en') return base
  const url = new URL(base)
  url.searchParams.set('lang', lang)
  return url.toString()
}